data=json.loads("\"diff --git a/skills/codex-delegate/scripts/relay.mjs b/skills/codex-delegate/scripts/relay.mjs\\nindex 70372f8..d4e80ca 100644\\n--- a/skills/codex-delegate/scripts/relay.mjs\\n+++ b/skills/codex-delegate/scripts/relay.mjs\\n@@ -56,6 +56,7 @@ import { spawn, execFileSync } from \\\"node:child_process\\\";\\n import { mkdirSync, writeFileSync, readFileSync, existsSync, appendFileSync } from \\\"node:fs\\\";\\n import { join, resolve, basename } from \\\"node:path\\\";\\n import { constants, tmpdir } from \\\"node:os\\\";\\n+import { windowsCodexCommand } from \\\"./windows-codex.mjs\\\";\\n \\n const SANDBOX_MODES = new Set([\\\"read-only\\\", \\\"workspace-write\\\", \\\"danger-full-access\\\"]);\\n \\n@@ -164,12 +165,7 @@ function timestamp() {\\n function buildArgv(opts, finalPath) {\\n   const argv = [\\\"exec\\\"];\\n   if (opts.resumeLast) argv.push(\\\"resume\\\", \\\"--last\\\");\\n-  // ponytail: shell:true on win32 (needed for the codex.cmd shim) doesn't quote\\n-  // args, so a temp path with spaces (C:\\\\Users\\\\First Last\\\\...) splits and the\\n-  // trailing \\\"-\\\" misparses (issue #3). Quote the only spaceable arg in argv.\\n-  // Ceiling: if quoting proves too blunt, drop shell:true and resolve the shim.\\n-  const outPath = process.platform === \\\"win32\\\" ? `\\\"${finalPath}\\\"` : finalPath;\\n-  argv.push(\\\"--json\\\", \\\"-o\\\", outPath);\\n+  argv.push(\\\"--json\\\", \\\"-o\\\", finalPath);\\n   // `-s`/`-C` are not accepted by `exec resume`; resume inherits the original\\n   // session's sandbox and working root, and we set the child process cwd below.\\n   if (!opts.resumeLast) {\\n@@ -253,10 +249,25 @@ function reportUnavailable(writeResult, resultPath) {\\n \\n function dispatchToCodex(opts, brief, run, writeResult) {\\n   const argv = buildArgv(opts, run.finalPath);\\n-  // shell:true on Windows so the codex.cmd shim resolves (see codexVersion). Safe:\\n-  // the brief is fed via child.stdin below — never argv — and argv holds only\\n-  // sandbox enums, model names, and file paths, with no shell metacharacters.\\n-  const child = spawn(\\\"codex\\\", argv, { cwd: opts.cd, stdio: [\\\"pipe\\\", \\\"pipe\\\", \\\"pipe\\\"], shell: process.platform === \\\"win32\\\" });\\n+  // Windows npm installs codex.cmd, which needs cmd.exe to resolve. Pass a\\n+  // single quoted command line instead of relying on Node's shell:true argv\\n+  // concatenation (which splits temp paths containing spaces).\\n+  let child;\\n+  if (process.platform === \\\"win32\\\") {\\n+    let commandLine;\\n+    try {\\n+      commandLine = windowsCodexCommand(argv);\\n+    } catch (err) {\\n+      const result = writeResult({ status: \\\"failed\\\", exitCode: 2, signal: null, threadId: null, finalMessage: \\\"\\\", touchedFiles: gitTouchedFiles(opts.cd), error: String(err.message) });\\n+      printSummary(result, run.resultPath);\\n+      process.exit(2);\\n+    }\\n+    child = spawn(\\\"cmd.exe\\\", [\\\"/d\\\", \\\"/v:off\\\", \\\"/s\\\", \\\"/c\\\", commandLine], {\\n+      cwd: opts.cd, stdio: [\\\"pipe\\\", \\\"pipe\\\", \\\"pipe\\\"], windowsHide: true,\\n+    });\\n+  } else {\\n+    child = spawn(\\\"codex\\\", argv, { cwd: opts.cd, stdio: [\\\"pipe\\\", \\\"pipe\\\", \\\"pipe\\\"] });\\n+  }\\n \\n   let threadId = null;\\n   let stdoutBuf = \\\"\\\";\\ndiff --git a/skills/codex-delegate/scripts/windows-codex.mjs b/skills/codex-delegate/scripts/windows-codex.mjs\\nnew file mode 100644\\nindex 0000000..2f2e646\\n--- /dev/null\\n+++ b/skills/codex-delegate/scripts/windows-codex.mjs\\n@@ -0,0 +1,18 @@\\n+/** Build a cmd.exe invocation for the Windows codex.cmd npm shim. */\\n+export function quoteForCmd(value) {\\n+  const arg = String(value);\\n+  // cmd expands %VAR% even inside double quotes. Reject it rather than allow\\n+  // an argument to be rewritten or interpreted as shell syntax.\\n+  // Double quotes and newlines also cannot safely be represented by this\\n+  // quoting scheme; Windows filesystem paths cannot contain double quotes.\\n+  if (/[%\\\"\\\\r\\\\n]/u.test(arg)) {\\n+    throw new Error('Windows Codex argument contains unsupported cmd.exe characters (%, \\\", or newline)');\\n+  }\\n+  if (!arg) return '\\\"\\\"';\\n+  if (/[\\\\s&()^|<>!]/u.test(arg)) return `\\\"${arg}\\\"`;\\n+  return arg;\\n+}\\n+\\n+export function windowsCodexCommand(argv) {\\n+  return ['codex', ...argv].map(quoteForCmd).join(' ');\\n+}\\ndiff --git a/tests/windows-codex.test.mjs b/tests/windows-codex.test.mjs\\nnew file mode 100644\\nindex 0000000..1cba0c1\\n--- /dev/null\\n+++ b/tests/windows-codex.test.mjs\\n@@ -0,0 +1,27 @@\\n+import test from 'node:test';\\n+import assert from 'node:assert/strict';\\n+import { quoteForCmd, windowsCodexCommand } from '../skills/codex-delegate/scripts/windows-codex.mjs';\\n+\\n+test('Windows temp profile with spaces keeps final path a single argument', () => {\\n+  const path = 'C:\\\\\\\\Users\\\\\\\\Mahmoud Sabry\\\\\\\\AppData\\\\\\\\Local\\\\\\\\Temp\\\\\\\\delegate-relay\\\\\\\\final.txt';\\n+  assert.equal(windowsCodexCommand(['exec', '--json', '-o', path, '-s', 'read-only', '-']),\\n+    `codex exec --json -o \\\"${path}\\\" -s read-only -`);\\n+});\\n+\\n+test('quotes shell metacharacters in every argument, not only the output path', () => {\\n+  assert.equal(quoteForCmd('a & b|c (d)^e<z>!'), '\\\"a & b|c (d)^e<z>!\\\"');\\n+  assert.equal(windowsCodexCommand(['exec', '-m', 'model (test)&more', '-']),\\n+    'codex exec -m \\\"model (test)&more\\\" -');\\n+  assert.equal(quoteForCmd(''), '\\\"\\\"');\\n+});\\n+\\n+test('rejects cmd expansion and syntax injection sequences', () => {\\n+  for (const arg of ['%COMSPEC%', 'x\\\" & calc & \\\"', 'x\\\\rwhoami', 'x\\\\nwhoami']) {\\n+    assert.throws(() => windowsCodexCommand(['exec', '-m', arg]), /unsupported cmd.exe characters/);\\n+  }\\n+});\\n+\\n+test('preserves ordinary POSIX-compatible argv spelling', () => {\\n+  assert.equal(windowsCodexCommand(['exec', '--json', '-o', 'C:\\\\\\\\temp\\\\\\\\final.txt', '-s', 'workspace-write', '-']),\\n+    'codex exec --json -o C:\\\\\\\\temp\\\\\\\\final.txt -s workspace-write -');\\n+});\\n\"").encode('utf-8')
